package handlers

import (
	"net/http"
	"strings"

	"github.com/gin-gonic/gin"

	"todo-app/apps/api/internal/concurrency"
	"todo-app/apps/api/internal/files"
	"todo-app/apps/api/internal/models"
	"todo-app/apps/api/internal/paginate"
	"todo-app/apps/api/internal/respond"
)

// The public contacts surface.
//
// Generated by grit with --public. Two read endpoints, mounted outside auth and
// guarded by an API key, for clients with no logged-in user: a storefront, a
// mobile app, a public directory.
//
// Regenerating the resource does NOT overwrite this file, so the allowlist
// below is yours to edit.

// publicContact is what an anonymous caller is allowed to see.
//
// An allowlist rather than the model. A column added next month is private
// until somebody adds it here, which is the correct default when the audience
// is the internet, and the opposite of the admin surface's default.
type publicContact struct {
	ID      string         `json:"id"`
	Name    string         `json:"name"`
	Email   string         `json:"email"`
	Phone   string         `json:"phone"`
	Profile *files.FileRef `json:"profile"`
	Version int            `json:"version"`
}

func toPublicContact(m models.Contact) publicContact {
	return publicContact{
		ID:      m.ID,
		Name:    m.Name,
		Email:   m.Email,
		Phone:   m.Phone,
		Profile: m.Profile,
		Version: m.Version,
	}
}

// ListPublic handles GET /api/v1/public/contacts.
//
// Supports ?search=, ?sort_by= and ?sort_order=, ?page= and ?page_size=,
// equality filters on the published columns, and a ?x_min= / ?x_max= window on
// the numeric ones.
func (h *ContactHandler) ListPublic(c *gin.Context) {
	c.Header("Cache-Control", "no-store")
	// The service decides what "live" means and it is not settable from here:
	// archived_at and the visibility column are deliberately absent from the
	// filter lists below, because a column listed there is settable from the
	// query string, and ?active=false would hand back rows somebody took down
	// on purpose.
	res, err := h.service().ListPublic(c.Request.Context(), paginate.Bind(c), paginate.Config{
		Searchable: []string{"name", "email", "phone"},
		Sortable:   map[string]bool{"name": true, "created_at": true},
		// Published columns only, plus foreign keys. Anything not listed is
		// ignored rather than rejected, so an unknown query param is never an
		// error.
		Filterable:      map[string]bool{"name": true},
		RangeFilterable: map[string]bool{},
		// Foreign keys accept a comma-separated list, so one request can ask
		// for a whole category subtree.
		InFilterable: map[string]bool{},
	})
	if err != nil {
		h.fail(c, err, "Failed to fetch contacts")
		return
	}

	out := make([]publicContact, 0, len(res.Data))
	for _, m := range res.Data {
		out = append(out, toPublicContact(m))
	}
	c.JSON(http.StatusOK, gin.H{"data": out, "meta": res.Meta})
}

// GetPublic handles GET /api/v1/public/contacts/:key.
//
// Looks up by id, so a public URL reads as something a person
// could type rather than a UUID.
func (h *ContactHandler) GetPublic(c *gin.Context) {
	c.Header("Cache-Control", "no-store")
	item, err := h.service().GetPublic(c.Request.Context(), c.Param("key"))
	if err != nil {
		h.fail(c, err, "Failed to load contact")
		return
	}
	c.JSON(http.StatusOK, gin.H{"data": toPublicContact(*item)})
}

func (h *ContactHandler) PublicCreate(c *gin.Context) {
	var req CreateContactRequest

	if err := c.ShouldBindJSON(&req); err != nil {
		respond.Fail(c, respond.CodeValidationError, err.Error())
		return
	}
	req.Name = strings.TrimSpace(req.Name)
	if req.Name == "" {
		respond.Validation(c, "Name is required", map[string]string{"name": "Name is required"})
		return
	}

	item := models.Contact{
		Name:    req.Name,
		Email:   req.Email,
		Phone:   req.Phone,
		Profile: req.Profile,
	}

	if err := h.service().Create(h.ctx(c), &item); err != nil {
		h.fail(c, err, "Failed to create contact")
		return
	}

	// events.Emitted(c, "contacts", "Contact", "created", item.ID, item.Name, "", nil, item)

	c.JSON(http.StatusCreated, gin.H{
		"data":    item,
		"message": "Contact created successfully",
	})
}

// PublicUpdate replaces the editable fields of a contact in the public directory.
func (h *ContactHandler) PublicUpdate(c *gin.Context) {
	var req CreateContactRequest
	if err := c.ShouldBindJSON(&req); err != nil {
		respond.Fail(c, respond.CodeValidationError, err.Error())
		return
	}
	req.Name = strings.TrimSpace(req.Name)
	if req.Name == "" {
		respond.Validation(c, "Name is required", map[string]string{"name": "Name is required"})
		return
	}
	if _, err := h.service().GetPublic(c.Request.Context(), c.Param("key")); err != nil {
		h.fail(c, err, "Failed to load contact")
		return
	}
	var email interface{} = strings.TrimSpace(req.Email)
	if email == "" {
		email = nil
	}
	item, err := h.service().Update(h.ctx(c), c.Param("key"), map[string]interface{}{
		"name": req.Name, "email": email, "phone": req.Phone, "profile": req.Profile,
	}, concurrency.FromRequest(c))
	if err != nil {
		h.fail(c, err, "Failed to update contact")
		return
	}
	c.JSON(http.StatusOK, gin.H{"data": toPublicContact(*item), "message": "Contact updated successfully"})
}

// PublicDelete removes a contact from the public directory using a soft delete.
func (h *ContactHandler) PublicDelete(c *gin.Context) {
	if _, err := h.service().GetPublic(c.Request.Context(), c.Param("key")); err != nil {
		h.fail(c, err, "Failed to load contact")
		return
	}
	if _, err := h.service().Delete(h.ctx(c), c.Param("key")); err != nil {
		h.fail(c, err, "Failed to delete contact")
		return
	}
	c.JSON(http.StatusOK, gin.H{"message": "Contact deleted successfully"})
}
